import { Given, When, Then, After } from '@cucumber/cucumber';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

// Real production entry from the adopted contract: `node src/pref.js <cmd>`.
const PREF_CLI = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../src/pref.js');

// Each call is a fresh Node process, so a set followed by a get crosses a
// process restart: nothing survives except what pref.js persisted to disk.
function runPref(world, ...args) {
  const result = spawnSync(process.execPath, [PREF_CLI, ...args], {
    cwd: world.scratchDir,
    env: { ...process.env, PREF_FILE: world.prefFile },
    encoding: 'utf8',
  });
  assert.equal(result.error, undefined, `failed to spawn pref.js: ${result.error}`);
  assert.equal(result.status, 0, `pref.js ${args.join(' ')} exited ${result.status}: ${result.stderr}`);
  return result;
}

Given('an isolated scratch project', function () {
  this.scratchDir = fs.mkdtempSync(path.join(os.tmpdir(), 'cs-1-pref-'));
  this.prefFile = path.join(this.scratchDir, 'pref.json');
  assert.equal(fs.existsSync(this.prefFile), false, 'scratch project must start with no stored preference');
});

Given('the preference is saved as {string}', function (value) {
  const set = runPref(this, 'set', value);
  this.setPid = set.pid;
  // The write must be on disk, not just reported: otherwise a get that echoes
  // argv or a cached value could pass without persistence.
  assert.equal(fs.existsSync(this.prefFile), true, 'set did not persist a preference file');
});

Given('the stored preference is replaced out of band with {string}', function (other) {
  fs.writeFileSync(this.prefFile, JSON.stringify({ value: other }));
});

When('the preference process is restarted and the preference is read with {string}', function (cmd) {
  const get = runPref(this, cmd);
  assert.notEqual(get.pid, this.setPid, 'get must run in a new process to count as a restart');
  this.readBack = get.stdout;
});

Then('the preference read back equals {string}', function (expected) {
  assert.strictEqual(this.readBack, expected);
});

Then('the preference read back does not equal {string}', function (saved) {
  assert.notStrictEqual(this.readBack, saved);
  // The negative control only proves oracle sensitivity if get actually read
  // the substituted value rather than failing or returning empty output.
  assert.strictEqual(this.readBack, JSON.parse(fs.readFileSync(this.prefFile, 'utf8')).value);
});

After(function () {
  if (this.scratchDir) fs.rmSync(this.scratchDir, { recursive: true, force: true });
});
